import{_ as n,a0 as d,w as l,s as c,I as i,x as s,a1 as a,A as t,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"在 Arch Linux 上安装 Docker | LCTT x X-CMD","titleTemplate":false,"description":"在 Arch Linux 上安装 Docker | LCTT (202311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Arch Linux 上安装 Docker | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Arch Linux 上安装 Docker | LCTT (202311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202311/20231030 Install Docker on Arch Linux","title":"在 Arch Linux 上安装 Docker","tag":"202311","desc":""},"relativePath":"202311/20231030 Install Docker on Arch Linux.md","filePath":"[post].md"}'),p={name:"202311/20231030 Install Docker on Arch Linux.md"};function k(h,e,u,g,b,m){const o=d("Link");return l(),c("div",null,[e[25]||(e[25]=i("h1",{id:"在-arch-linux-上安装-docker",tabindex:"-1"},[s("在 Arch Linux 上安装 Docker "),i("a",{class:"header-anchor",href:"#在-arch-linux-上安装-docker","aria-label":"Permalink to “在 Arch Linux 上安装 Docker”"},"​")],-1)),e[26]||(e[26]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202311/09/154128mctmdkdd0jolyv0k.png",alt:""})],-1)),e[27]||(e[27]=i("blockquote",null,[i("p",null,"了解如何在 Arch Linux 上安装 Docker，并使用 Docker Compose 和制表符补全为运行容器做好准备。")],-1)),i("p",null,[e[1]||(e[1]=s("在 Arch Linux 上安装 Docker 很简单。它可以在 Extra 仓库中找到，你可以简单地 ",-1)),a(o,{href:"https://itsfoss.com/pacman-command/"},{default:t(()=>[...e[0]||(e[0]=[s("执行 pacman 魔法",-1)])]),_:1}),e[2]||(e[2]=s("：",-1))]),e[28]||(e[28]=r('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S docker</span></span></code></pre></div><p>但要在 Arch Linux 上正确运行 Docker，还需要执行更多步骤。</p><h3 id="让-arch-docker-做好准备" tabindex="-1">让 Arch Docker 做好准备 <a class="header-anchor" href="#让-arch-docker-做好准备" aria-label="Permalink to “让 Arch Docker 做好准备”">​</a></h3><p>这一切都归结为以下步骤：</p><ul><li>从 Arch 仓库安装 Docker</li><li>启动 Docker 守护进程并在每次启动时自动运行</li><li>将用户添加到 <code>docker</code> 组以运行 <code>docker</code> 命令而无需 <code>sudo</code></li></ul><p>让我们看看详细步骤。</p><h4 id="步骤-1-安装-docker-包" tabindex="-1">步骤 1：安装 Docker 包 <a class="header-anchor" href="#步骤-1-安装-docker-包" aria-label="Permalink to “步骤 1：安装 Docker 包”">​</a></h4><p>打开终端并使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S docker</span></span></code></pre></div><p>输入密码并在询问时按 <code>Y</code>。</p><p><img src="https://itsfoss.com/content/images/2023/10/installing-docker-arch-linux.png" alt=""></p><p>这可能需要一些时间，具体取决于你使用的镜像。</p><blockquote><p>💡 如果你看到找不到包或 404 错误，那么你的同步数据库可能是旧的。使用以下命令更新系统（它将下载大量软件包并需要时间）： <code>sudo pacman -Syu</code></p></blockquote><h4 id="步骤-2-启动-docker-守护进程" tabindex="-1">步骤 2：启动 docker 守护进程 <a class="header-anchor" href="#步骤-2-启动-docker-守护进程" aria-label="Permalink to “步骤 2：启动 docker 守护进程”">​</a></h4><p>Docker 已安装但未运行。你应该在<strong>第一次运行 Docker 命令</strong>之前启动 Docker 守护进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start docker.service</span></span></code></pre></div><p>我还建议启用 Docker 服务，以便 Docker 守护进程在系统启动时自动启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable docker.service</span></span></code></pre></div><p>这样，你就可以开始运行 <code>docker</code> 命令了。你不再需要手动启动 Docker 服务。</p><p><img src="https://itsfoss.com/content/images/2023/10/start-docker-daemon-arch-linux.png" alt=""></p><h4 id="步骤-3-将用户添加到-docker-组" tabindex="-1">步骤 3：将用户添加到 docker 组 <a class="header-anchor" href="#步骤-3-将用户添加到-docker-组" aria-label="Permalink to “步骤 3：将用户添加到 docker 组”">​</a></h4><p>Docker 已安装并且 Docker 服务正在运行。你几乎已准备好运行 <code>docker</code> 命令。</p><p>但是，默认情况下，你需要将 <code>sudo</code> 与 <code>docker</code> 命令一起使用。这很烦人。</p><p>为了避免在每个 <code>docker</code> 命令中使用 <code>sudo</code>，你可以将自己（或任何其他用户）添加到 <code>docker</code> 组，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -aG docker $USER</span></span></code></pre></div><p><strong>你必须注销（或关闭终端）并重新登录才能使上述更改生效。如果你不想这样做，请使用以下命令：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>newgrp docker</span></span></code></pre></div><p>现在已经准备好了。我们来测试一下。</p><h4 id="步骤-4-验证-docker-安装" tabindex="-1">步骤 4：验证 docker 安装 <a class="header-anchor" href="#步骤-4-验证-docker-安装" aria-label="Permalink to “步骤 4：验证 docker 安装”">​</a></h4><p>Docker 本身提供了一个很小的 Docker 镜像来测试 Docker 安装。运行它并查看是否一切正常：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker run hello-world</span></span></code></pre></div><p>你应该看到类似这样的输出，表明 Docker 成功运行：</p><p><img src="https://itsfoss.com/content/images/2023/10/docker-running-successfully-arch-linux.png" alt=""></p><p>恭喜！ 你已经在 Arch Linux 上成功安装了 Docker。</p><h3 id="可选-安装-docker-compose" tabindex="-1">可选：安装 Docker Compose <a class="header-anchor" href="#可选-安装-docker-compose" aria-label="Permalink to “可选：安装 Docker Compose”">​</a></h3><p>Docker Compose 已经成为 Docker 不可或缺的一部分。它允许你管理多个容器应用。</p>',36)),i("p",null,[e[4]||(e[4]=s("较早的经典 Compose 由 ",-1)),e[5]||(e[5]=i("code",null,"docker-compose",-1)),e[6]||(e[6]=s(" Python 软件包提供。Docker 还将其移植到 Go 中，并通过 ",-1)),e[7]||(e[7]=i("code",null,"docker compose",-1)),e[8]||(e[8]=s(" 提供，但该软件包附带 ",-1)),a(o,{href:"https://www.docker.com/products/docker-desktop/"},{default:t(()=>[...e[3]||(e[3]=[s("Docker Desktop",-1)])]),_:1}),e[9]||(e[9]=s("。",-1))]),e[29]||(e[29]=r(`<p>在这个阶段，我建议使用经典的 <code>docker-compose</code> 插件并使用以下命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S docker-compose</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/10/install-docker-compose.png" alt=""></p><h3 id="故障排除技巧" tabindex="-1">故障排除技巧 <a class="header-anchor" href="#故障排除技巧" aria-label="Permalink to “故障排除技巧”">​</a></h3><p>以下是你可能遇到的一些常见问题以及可能的解决方案：</p><h4 id="制表符补全不适用于-docker-子命令" tabindex="-1">制表符补全不适用于 docker 子命令 <a class="header-anchor" href="#制表符补全不适用于-docker-子命令" aria-label="Permalink to “制表符补全不适用于 docker 子命令”">​</a></h4><p>如果你想对 <code>docker</code> 命令选项使用制表符补全（例如将 <code>im</code> 补全到 <code>images</code> 等），请安装 <code>bash-completion</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S bash-completion</span></span></code></pre></div><p>关闭终端并启动一个新终端。你现在应该能够通过 <code>docker</code> 命令使用制表符补全功能。</p><h4 id="无法连接到-docker-守护进程错误" tabindex="-1">无法连接到 Docker 守护进程错误 <a class="header-anchor" href="#无法连接到-docker-守护进程错误" aria-label="Permalink to “无法连接到 Docker 守护进程错误”">​</a></h4><p>如果你看到以下错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker: Cannot connect to the Docker daemon at unix:///var/run/docker.sock. Is the docker daemon running?.</span></span>
<span class="line"><span>See &#39;docker run --help&#39;.</span></span></code></pre></div><p>那是因为 Docker 守护进程没有运行。参考步骤 2，启动 Docker 服务，确保其正在运行并启用它，以便 Docker 守护进程在每次启动时自动运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start docker.service</span></span>
<span class="line"><span>sudo systemctl enable docker.service</span></span></code></pre></div><h4 id="尝试连接到-docker-守护程序套接字时权限被拒绝" tabindex="-1">尝试连接到 Docker 守护程序套接字时权限被拒绝 <a class="header-anchor" href="#尝试连接到-docker-守护程序套接字时权限被拒绝" aria-label="Permalink to “尝试连接到 Docker 守护程序套接字时权限被拒绝”">​</a></h4><p>如果你看到此错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ddocker: permission denied while trying to connect to the Docker daemon socket at unix:///var/run/docker.sock: Post &quot;http://%2Fvar%2Frun%2Fdocker.sock/v1.24/containers/create&quot;: dial unix /var/run/docker.sock: connect: permission denied.</span></span>
<span class="line"><span>See &#39;docker run --help&#39;.</span></span></code></pre></div><p>这是因为你需要使用 <code>sudo</code> 运行 <code>docker</code> 命令，或者将用户添加到 <code>docker</code> 组以在不使用 <code>sudo</code> 的情况下运行 <code>docker</code> 命令。</p><p>我希望这篇简短的文章可以帮助你在 Arch Linux 上运行 Docker。</p><p><em>（题图：MJ/9951f8bf-d2e5-4335-bd86-ebf89cba654d）</em></p><hr>`,21)),i("p",null,[e[11]||(e[11]=s("via: ",-1)),a(o,{href:"https://itsfoss.com/install-docker-arch-linux/"},{default:t(()=>[...e[10]||(e[10]=[s("https://itsfoss.com/install-docker-arch-linux/",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=s("作者：",-1)),a(o,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...e[12]||(e[12]=[s("Abhishek Prakash",-1)])]),_:1}),e[17]||(e[17]=s(" 选题：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[13]||(e[13]=[s("lujun9972",-1)])]),_:1}),e[18]||(e[18]=s(" 译者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:t(()=>[...e[14]||(e[14]=[s("geekpi",-1)])]),_:1}),e[19]||(e[19]=s(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:t(()=>[...e[15]||(e[15]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[22]||(e[22]=s("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[20]||(e[20]=[s("LCTT",-1)])]),_:1}),e[23]||(e[23]=s(" 原创编译，",-1)),a(o,{href:"https://linux.cn/"},{default:t(()=>[...e[21]||(e[21]=[s("Linux中国",-1)])]),_:1}),e[24]||(e[24]=s(" 荣誉推出",-1))])])}const C=n(p,[["render",k]]);export{D as __pageData,C as default};
